import sys


def solve(N: int, A: int, B: int):
    if A > B:
        tmp = A
        A = B
        B = A

    count = 0
    while True:
        if (B - A) % 2 == 0:
            count += (B - A) // 2
            break
        elif A != 1 and B != N:
            if B-1 < N-A:
                count += A-1
                A = 1
                B = B - (A-1)

